def roman_to_int(s: str) -> int:
    """Convert a Roman numeral (I, V, X, L, C, D, M with subtractive pairs) to an integer."""
    if not s:
        return 0
    values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    prev = 0
    for ch in reversed(s.upper()):
        val = values.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

def second_largest(nums: list) -> int:
    """Return the second largest distinct value; raise ValueError if there is none."""
    if not nums:
        raise ValueError("List must contain at least two distinct values")
    distinct = set(nums)
    if len(distinct) < 2:
        raise ValueError("List must contain at least two distinct values")
    # largest and second largest
    first = second = None
    for v in distinct:
        if first is None or v > first:
            second = first
            first = v
        elif second is None or v > second:
            second = v
    return second

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.

    Supports optional dollar sign, commas as thousands separators, and an optional
    decimal component. Raises ValueError if the string does not represent a
    valid number.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    s = s.strip()
    if not s:
        raise ValueError("Empty string")
    # Remove leading $ if present
    if s[0] == "$":
        s = s[1:]
    if not s:
        raise ValueError("String contains only '$'")
    # Validate characters: digits, comma, dot
    allowed = set("0123456789,.")
    if any(c not in allowed for c in s):
        raise ValueError(f"Invalid character in price string: {s}")
    # Remove commas
    s = s.replace(",", "")
    # Ensure at most one dot
    if s.count(".") > 1:
        raise ValueError(f"Too many decimal points in price string: {s}")
    # If dot present, ensure fractional part is digits
    if "." in s:
        int_part, frac_part = s.split(".")
        if not int_part.isdigit() or (frac_part and not frac_part.isdigit()):
            raise ValueError(f"Invalid numeric format: {s}")
    else:
        if not s.isdigit():
            raise ValueError(f"Invalid numeric format: {s}")
    return float(s)

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v: str):
        parts = v.split('.')
        # Ensure at least 3 parts, pad with zeros if missing
        parts = (parts + ['0', '0', '0'])[:3]
        return tuple(int(p) for p in parts)
    return sorted(vs, key=key)

