import datetime

def days_between(a: str, b: str) -> int:
    """Number of days from ISO date a to ISO date b (b - a)."""
    try:
        date_a = datetime.datetime.strptime(a, "%Y-%m-%d").date()
        date_b = datetime.datetime.strptime(b, "%Y-%m-%d").date()
    except Exception as e:
        raise ValueError(f"Invalid date format: {e}")
    delta = date_b - date_a
    return delta.days

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Sort by start
    iv = sorted(iv, key=lambda x: x[0])
    merged = [iv[0]]
    for current in iv[1:]:
        last = merged[-1]
        # If current starts before or at last's end, merge (touching also merges)
        if current[0] <= last[1]:
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)
    return merged

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float.
    Accepts optional leading '$', commas as thousands separators, and an optional decimal part.
    Raises ValueError for malformed inputs.
    """
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    s = s.strip()
    if s.startswith('$'):
        s = s[1:]
    # After removing $ allow digits, commas, and at most one dot
    if not s:
        raise ValueError("Empty price string")
    # Validate characters
    allowed = set("0123456789,.")
    if any(c not in allowed for c in s):
        raise ValueError("Invalid characters in price string")
    # Ensure at most one dot
    if s.count('.') > 1:
        raise ValueError("Multiple decimal points")
    # Ensure commas are correctly placed: either no commas or groups of three
    parts = s.split('.')
    int_part = parts[0]
    if ',' in int_part:
        groups = int_part.split(',')
        if len(groups) < 2:
            raise ValueError("Misplaced comma")
        # First group can be 1-3 digits, subsequent must be exactly 3
        if not (1 <= len(groups[0]) <= 3):
            raise ValueError("Misplaced comma in integer part")
        if any(len(g) != 3 for g in groups[1:]):
            raise ValueError("Misplaced comma in integer part")
        int_part = ''.join(groups)
    cleaned = int_part
    if len(parts) == 2:
        cleaned += '.' + parts[1]
    try:
        return float(cleaned)
    except ValueError:
        raise ValueError("Could not convert price to float")

